import * as THREE from 'three/webgpu';
import * as TSL from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Content group positioned in scene
  const content = new THREE.Group();
  content.position.set(0, 3, 0);
  group.add(content);

  // Load ceramic grain texture
  const texture = ctx.textureLoader.load('/prism-assets/chrome/ceramic-grain.map.png');

  // Create billboard plane (512x320 aspect ratio = 1.6)
  const geometry = new THREE.PlaneGeometry(1.6, 1);
  const colorNode = TSL.texture(texture);
  const material = new THREE.MeshBasicNodeMaterial({
    colorNode,
    transparent: true,
    side: THREE.DoubleSide,
  });

  // Add textured background mesh
  const mesh = new THREE.Mesh(geometry, material);
  content.add(mesh);

  // Render text overlay via fontAtlas
  if (ctx.fontAtlas) {
    let text = 'Features';
    if (config.textContent && Array.isArray(config.textContent)) {
      const item = config.textContent[0];
      text = typeof item === 'string' ? item : item?.text || item?.content || text;
    }

    const textMesh = ctx.fontAtlas.render(text, {
      fontSize: 0.34,
      fontWeight: 400,
      fontFamily: 'Lora',
      color: '#16161d',
    });

    if (textMesh) {
      textMesh.position.z = 0.1;
      content.add(textMesh);
    }
  }

  // Cleanup resources
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  group.userData.handlers = {};

  return group;
}
